import React, { useState } from "react";
import { QrReader } from "react-qr-reader";

function QRScanner() {

  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");

  const handleScan = async (result) => {

    if (!result) return;

    const qrValue = result?.text;

    try {

      const verify = await fetch(
        `http://localhost:5000/verify-user/${qrValue}`
      );

      const verifyData = await verify.json();

      if (!verifyData.success) {

        setStatus("notfound");
        setStudent(null);
        return;

      }

      setStudent(verifyData.user);

      const attendance = await fetch(
        `http://localhost:5000/mark-attendance/${qrValue}`,
        {
          method: "PUT"
        }
      );

      const attendanceData = await attendance.json();

      if (attendanceData.success) {

        setStatus("success");

      } else {

        setStatus("already");

      }

    } catch (error) {

      console.log(error);
      setStatus("servererror");

    }

  };

  return (

    <div style={{ textAlign: "center", marginTop: "40px" }}>

      <h2>QR Attendance Scanner</h2>

      <div style={{ width: "350px", margin: "auto" }}>

        <QrReader
          constraints={{ facingMode: "environment" }}
          onResult={(result, error) => {
            if (result) handleScan(result);
          }}
          style={{ width: "100%" }}
        />

      </div>

      {student && (

        <div
          style={{
            width: "320px",
            margin: "20px auto",
            padding: "20px",
            background: "#f5f5f5",
            borderRadius: "10px"
          }}
        >

          <h3>{student.name}</h3>
          <p>{student.college_name}</p>

          {status === "success" && (
            <h2 style={{ color: "green" }}>✔ Attendance Marked</h2>
          )}

          {status === "already" && (
            <h2 style={{ color: "red" }}>Already Scanned</h2>
          )}

          {status === "notfound" && (
            <h2 style={{ color: "orange" }}>User Not Found</h2>
          )}

          {status === "servererror" && (
            <h2 style={{ color: "red" }}>Server Error</h2>
          )}

        </div>

      )}

    </div>

  );
}

export default QRScanner;
